<script setup>
import { Link, router, useForm } from '@inertiajs/vue3';
import { reactive } from 'vue';
import AssessmentLayout from './AssessmentLayout.vue';
const props = defineProps({ user: Object, ledger: Object, summary: Object, sourceOptions: Array, filters: Object });
const filter = reactive({ search: props.filters.search || '', source: props.filters.source || 'all', direction: props.filters.direction || 'all' });
const adjustment = useForm({ direction: 'add', amount: 1, reason: '' });
const apply = () => router.get(route('redesign.users.ledger',props.user.id),filter,{preserveState:true});
</script>
<template><AssessmentLayout title="Ledger transaksi pengguna" :subtitle="`${user.name} · @${user.username || '—'}`" breadcrumb="Komunitas & pengguna"><template #action><Link class="secondary" :href="route('redesign.users.edit',user.id)">Edit pengguna</Link></template><div class="panel" style="margin-bottom:20px"><div class="fields"><div><span class="muted">Saldo gold</span><h2>{{ summary.current_gold }}</h2></div><div><span class="muted">Total masuk</span><h2>{{ summary.income_total }}</h2></div><div><span class="muted">Total keluar</span><h2>{{ summary.expense_total }}</h2></div><div><span class="muted">Transaksi</span><h2>{{ summary.transaction_count }}</h2></div></div></div><div class="layout"><section class="panel"><h2>Riwayat transaksi</h2><form class="filters" @submit.prevent="apply"><input v-model="filter.search" placeholder="Cari transaksi" /><select v-model="filter.source"><option value="all">Semua sumber</option><option v-for="source in sourceOptions" :key="source.key" :value="source.key">{{ source.label }}</option></select><select v-model="filter.direction"><option value="all">Semua arah</option><option value="income">Masuk</option><option value="expense">Keluar</option><option value="neutral">Netral</option></select><button class="secondary">Terapkan</button></form><div class="table-wrap"><table><thead><tr><th>Waktu</th><th>Sumber</th><th>Keterangan</th><th>Perubahan</th></tr></thead><tbody><tr v-for="(row,index) in ledger.data" :key="index"><td>{{ row.occurred_at }}</td><td>{{ row.source_label }}</td><td>{{ row.note || row.reference || '—' }}</td><td>{{ row.gold_change > 0 ? '+' : '' }}{{ row.gold_change }}</td></tr><tr v-if="!ledger.data?.length"><td colspan="4">Belum ada transaksi.</td></tr></tbody></table></div><div class="pager"><Link v-for="(link,index) in ledger.links" :key="index" :href="link.url || '#'" :class="{active:link.active,disabled:!link.url}" v-html="link.label" /></div></section><aside><form class="panel fields" @submit.prevent="adjustment.post(route('admin.users.gold-adjustment',user.id),{onSuccess:()=>adjustment.reset('amount','reason')})"><h2 class="wide">Sesuaikan gold</h2><label class="wide">Arah<select v-model="adjustment.direction"><option value="add">Tambah</option><option value="subtract">Kurangi</option></select></label><label class="wide">Jumlah<input v-model.number="adjustment.amount" type="number" min="1" max="1000000" required /><span class="error">{{ adjustment.errors.amount }}</span></label><label class="wide">Alasan<input v-model="adjustment.reason" maxlength="255" /></label><button class="primary" :disabled="adjustment.processing">Simpan penyesuaian</button></form></aside></div></AssessmentLayout></template>
